/*
 * prog35_perfect_numbers
 *
 * The original binary implements a small utility that classifies a
 * positive integer as *deficient*, *perfect* or *abundant* based on the
 * sum of its proper divisors.  The program also contains a few
 * defensive checks that were heavily obfuscated in the compiled
 * version:
 *
 *   • No command‑line argument      → prints "NO_INPUT"
 *   • Argument not a decimal integer → prints "BAD_INPUT"
 *   • Value > 1 000 000            → prints "OUT_OF_RANGE"
 *
 * For a valid integer n (1 ≤ n ≤ 1 000 000) the program computes the
 * sum of all proper divisors of n (i.e. all i with 1 ≤ i < n and n % i == 0)
 * and prints one of the three messages:
 *
 *       n=%ld sum=%ld deficient\n
 *       n=%ld sum=%ld perfect\n
 *       n=%ld sum=%ld abundant\n
 *
 * The behaviour reproduced below matches the observable output of the
 * original binary for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    long n, sum = 0;
    char *endptr = NULL;

    /* 1) Argument presence check */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2) Parse the argument as a base‑10 integer */
    n = strtol(argv[1], &endptr, 10);

    /* strtol failed to consume any characters or left trailing data? */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3) Range check (the original binary limits n to 1 000 000) */
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* The original code only makes sense for positive numbers.
     * Treat non‑positive values as bad input – this matches the
     * behaviour observed in the decompiled state machine. */
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }

    /* 4) Compute the sum of proper divisors of n */
    for (long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            long d = n / i;          /* paired divisor */

            if (i != n)               /* i is a proper divisor */
                sum += i;

            if (d != i && d != n)     /* the paired divisor, also proper */
                sum += d;
        }
    }

    /* 5) Classification and output */
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum < n) {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    } else {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    }

    return 0;
}
